(function(){const src='data:image/jpeg;base64,';function apply(root){(root||document).querySelectorAll('.ac-avatar,.ac-mini-avatar').forEach(el=>{el.textContent='';el.style.backgroundImage='url("'+src+'")';el.style.backgroundSize='cover';el.style.backgroundPosition='center 35%';el.style.backgroundRepeat='no-repeat';el.style.color='transparent';});}function boot(){apply(document);new MutationObserver(m=>m.forEach(x=>x.addedNodes.forEach(n=>{if(n.nodeType===1){if(n.matches?.('.ac-avatar,.ac-mini-avatar'))apply(n.parentNode);else apply(n);}}))).observe(document.body,{childList:true,subtree:true});}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();})();